                .call(() -> {
                    throw new RuntimeException("Any error");
                })
                .map(x -> StringReply.newBuilder().setMessage(x.toString()).build())
                .collect().asList()
                .replaceWith(StringReply.newBuilder().setMessage("DONE").build());
