                        throw new RuntimeException("We reached 3, error here");
                    }
                    return StringReply.newBuilder().setMessage(x.toString()).build();
                })
                .collect().asList()
                .replaceWith(StringReply.newBuilder().setMessage("DONE").build());
    }

