@(require (except-in "utils.rkt" _fun)
          (for-label scheme/match
                     (only-in ffi/unsafe/static _fun))
          (for-syntax racket/base)
          scribble/eval
          scribble/racket)

@(begin
   (define-syntax-rule (define-dynamic_fun id)
